"""Validates the range argument"""
def validateRange(rangeStr: str) -> bool {
    try {
        ranges = rangeStr.split(",", 1);
        rangeFrom = 0 if ranges[0] == "" else int(ranges[0]);
        rangeTo = 0 if ranges[1] == "" else int(ranges[1]);
        if ranges == ["", ""] {
            return False;
        }
        if (ranges[0] != "" and rangeFrom < 0) or (ranges[1] != "" and rangeTo < 0) {
            return False;
        } elif ranges[0] != "" and ranges[1] != "" {
            if rangeFrom == rangeTo or rangeFrom > rangeTo or rangeFrom <= 0 or rangeTo <= 0 {
                return False;
            }
        }
    } except (ValueError, IndexError, AttributeError) {
        return False;
    }
    return True;
}

"""A meta-feature that will produce the set difference of two boolean features
    (will have keys set to 1 only for those features that occur in the first set but not in the
    second).

    @rtype: dict
    @return: dictionary with keys for key occurring with the first feature but not the second, and \
        keys equal to 1
    """
def set_difference(tree: str, context: dict[str, dict[str, dict[str, int]]], attribs: list[str]) -> dict[str, int] {
    ret = {};
    for (key, val) in context['feats'][attribs[0]].items() {
        if key not in context['feats'][attribs[1]] {
            ret[key] = val;
        }
    }
    return ret;
}

"""Find the highest common factor of two numbers."""
def find_hcf(a: int, b: int) -> int {
    if b == 0 {
        return a;
    }
    return find_hcf(b, a % b);
}

"""Returns None if the specified value is null, else returns the value."""
def none_to_null(value: str | int | float | bool | list[int] | None) -> str | int | float | bool | list[int] {
    return "null" if value == None else value;
}

"""
Ensures that the name of object used to create paths in file system do not
contain characters that would be handled erroneously (e.g. \ or / that
normally separate file directories).
"""
def correct_name(name: str) -> str {
    corrected_name = name.replace(" ", "_");
    corrected_name = corrected_name.replace("\\", "_");
    corrected_name = corrected_name.replace("/", "_");
    corrected_name = corrected_name.replace(":", "_");
    return corrected_name;
}

"""Build INSERT column names, placeholders, and values from (option, value) pairs."""
def get_insert_components(options: list[tuple[str, str]]) -> tuple[str, str, tuple[str, ...]] {
    col_names = ','.join(opt[0] for opt in options);
    placeholders = ','.join(['?' for _ in options]);
    if len(col_names) > 0 {
        col_names = ',' + col_names;
    }
    if len(placeholders) > 0 {
        placeholders = ',' + placeholders;
    }
    values = tuple(opt[1] for opt in options);
    return (col_names, placeholders, values);
}

glob CONTENT_CHUNK_SIZE = 50;

"""
    Given some raw bytes, return a display string
    Only show the beginning and end of largish (2x CONTENT_CHUNK_SIZE) arrays.
    """
def split_chunk_for_display(raw_bytes: bytes) -> str {
    if len(raw_bytes) > 2 * CONTENT_CHUNK_SIZE {
        return repr(raw_bytes[:CONTENT_CHUNK_SIZE]) + " ... " + repr(raw_bytes[-CONTENT_CHUNK_SIZE:]);
    }
    return repr(raw_bytes);
}

