"""Transforms a dict with unique sequential integer indices into an array"""
def arrayizeDict(g: dict[int, int]) -> list[int | None] {
    max_key = max(g.keys());
    result: list[int | None] = [None for _ in range(max_key)];
    for (k, v) in g.items() {
        result[k - 1] = v;
    }
    return result;
}

"""fitness_function(solution, answer) Returns a fitness score of a solution compaired to the desired answer. This score is the absolute 'ascii' distance between characters."""
def fitness_function(solution: bytes, answer: bytes) -> int {
    return sum(abs(solution[i] - answer[i]) for i in range(len(answer)));
}

"""Merge a single row or column in 2048."""
def merge(line: list[int]) -> list[int] {
    new_line = [x for x in line if x != 0];
    while len(new_line) < len(line) {
        new_line.append(0);
    }
    for ind in range(len(new_line) - 1) {
        if new_line[ind] == new_line[ind + 1] {
            new_line[ind] *= 2;
            new_line.pop(ind + 1);
            new_line.append(0);
        }
    }
    return new_line;
}

