"""Prepare filters (kwargs{}) for django queryset for mongodb
       where fields contain strings are checked like
       exact | startswith | contains | endswith

    >>> mongodb_str_filter(21, '1')
    '21'
    >>> mongodb_str_filter(21, '2')
    {'$regex': '^21'}
    >>> mongodb_str_filter(21, '3')
    {'$regex': '.*21.*'}
    >>> mongodb_str_filter(21, '4')
    {'$regex': '21$'}
    """
def mongodb_str_filter(base_field: Any, base_field_type: Any) -> object {
    q = '';
    base_field = str(base_field);
    if (base_field != '') {
        if (base_field_type == '1') {
            q = base_field;
        }
        if (base_field_type == '2') {
            q = {'$regex': str(('^' + base_field))};
        }
        if (base_field_type == '3') {
            q = {'$regex': str(('.*' + base_field + '.*'))};
        }
        if (base_field_type == '4') {
            q = {'$regex': str((base_field + '$'))};
        }
    }
    return q;
}

"""
In this algorithm, we want to find whether element x belongs to a set of numbers stored in an array numbers[]. Where l and r represent the left and right index of a sub-array in which searching operation should be performed.
"""
def maf_binary(sorted_array: list[int], value: int) -> int | None {
    min = 0;
    max = len(sorted_array) - 1;
    while min <= max {
        mid = (min + max) // 2;
        if sorted_array[mid] > value {
            max = mid - 1;
        } elif sorted_array[mid] < value {
            min = mid + 1;
        } else {
            return mid;
        }
    }
}

"""
    Tells if streets `st1`, `st2` are connected.

    Each tuple means:

    * 0 or 1 mean first or last extremity or the first street
    * 0 or 1 mean first or last extremity or the second street

    ``((0, 1),)`` means the first point of the first street is connected
    to the second extremity of the second street.
"""
def connect_streets(st1: list[tuple[float, float]], st2: list[tuple[float, float]]) -> tuple[tuple[int, int], ...] | None {
    (a1, b1) = (st1[0], st1[-1]);
    (a2, b2) = (st2[0], st2[-1]);
    connect: list[tuple[int, int]] = [];
    if a1 == a2 {
        connect.append((0, 0));
    }
    if a1 == b2 {
        connect.append((0, 1));
    }
    if b1 == a2 {
        connect.append((1, 0));
    }
    if b1 == b2 {
        connect.append((1, 1));
    }
    return tuple(connect) if connect else None;
}

