"""
Determine if the given graph is bipartite.

Time complexity is O(|E|)
Space complexity is O(|V|)
"""
def check_bipartite(adj_list: list[list[int]]) -> bool {
    vertices = len(adj_list);
    set_type = [-1 for v in range(vertices)];
    set_type[0] = 0;
    queue = [0];
    while queue {
        current = queue.pop(0);
        if adj_list[current][current] {
            return False;
        }
        for adjacent in range(vertices) {
            if adj_list[current][adjacent] {
                if set_type[adjacent] == set_type[current] {
                    return False;
                }
                if set_type[adjacent] == -1 {
                    set_type[adjacent] = 1 - set_type[current];
                    queue.append(adjacent);
                }
            }
        }
    }
    return True;
}

"""
Returns a copy of s, only including positions that are multiples of n

A position is a multiple of n if pos % n == 0.
"""
def `skip(s: str, n: int) -> str {
    assert `type(s) == str and len(s) > 0;
    assert `type(n) == int and n > 0;
    var = [];
    var2 = True;
    pos = 0;
    count = 1;
    while var2 {
        if pos % n == 0 and count <= len(s) {
            var.append(s[pos]);
            pos += 1;
            count += 1;
        } elif pos % n != 0 and count <= len(s) {
            pos += 1;
            count += 1;
        } else {
            var2 = False;
        }
    }
    return ''.join(var);
}

glob PAGE_SIZE = 1980;

"""Simple generator that paginates text."""
def paginate(text: str) -> list[str] {
    last = 0;
    pages = [];
    appd_index = 0;
    curr = 0;
    for curr in range(0, len(text)) {
        if curr % PAGE_SIZE == 0 {
            pages.append(text[last:curr]);
            last = curr;
            appd_index = curr;
        }
    }
    if appd_index != len(text) - 1 {
        pages.append(text[last:curr]);
    }
    return list(filter(lambda (a: str) { a != ''; }, pages));
}

