"""
		Discretize a yaw angle into the 4 canonical yaw angles/directions
	"""
def discretize_yaw(yaw: float) -> int {
    yaw_normalized = 360 + yaw if yaw < 0 else yaw;
    if (yaw_normalized >= 315 and yaw_normalized <= 360) or (yaw_normalized >= 0 and yaw_normalized < 45) {
        return 0;
    } elif yaw_normalized >= 45 and yaw_normalized < 135 {
        return 90;
    } elif yaw_normalized >= 135 and yaw_normalized < 225 {
        return 180;
    } else {
        return -90;
    }
}

"""
    Calculate the multiplicative modifier for a pokemon's stat.

    Args:
        pokemon (Pokemon): The pokemon for whom we are calculating.
        stat (str): The stat for which we are calculating this for.

    Returns:
        The multiplier to apply to that pokemon's stat.

    """
def calc_boost_factor(pokemon: dict[str, dict[str, int]], stat_name: str) -> float {
    boost = pokemon["boosts"][stat_name];
    return max(2, 2 + boost) / max(2, 2 - boost);
}

