}

"""
    Gets transition frequency color

    Parameters
    ----------
    trans_count
        Current transition count
    min_trans_count
        Minimum transition count
    max_trans_count
        Maximum transition count

    Returns
    ----------
    color
        Frequency color for visible transition
    """
def get_trans_freq_color(
    trans_count: float,
    min_trans_count: float,
    max_trans_count: float
) -> str {
    trans_base_color = int(
        255 - 100 * (trans_count - min_trans_count) / (max_trans_count - min_trans_count + 0.00001)
    );
    trans_base_color_hex = str(hex(trans_base_color))[2:].upper();
    return "#" + trans_base_color_hex + trans_base_color_hex + "FF";
}

"""
    Return the prefix for the given headword,
    of length length.

    :param headword: the headword string
    :type  headword: unicode
    :param length: prefix length
    :type  length: int
    :rtype: unicode
    """
def get_prefix(headword: Any, length: Any) -> object {
    if (headword is None) {
        return None;
    }
    lowercased = headword.lower();
    if (ord(lowercased[0]) < 97) {
        return "SPECIAL";
    }
    if (len(lowercased) < length) {
        return lowercased;
    }
    return lowercased[0:length];
}

