"""Returns the image type from the first few bytes."""
def get_image_mime_type(data: bytes) -> str {
    if data.startswith(b'\x89PNG\r\n\x1a\n') {
        return "image/png";
    } elif data[0:3] == b'\xff\xd8\xff' or data[6:10] in (b'JFIF', b'Exif') {
        return "image/jpeg";
    } elif data.startswith((b'GIF87a', b'GIF89a')) {
        return "image/gif";
    } elif data.startswith(b'RIFF') and data[8:12] == b'WEBP' {
        return "image/webp";
    } else {
        raise ValueError("Unsupported image type given");
    }
}

"""Checks to see if a task is complete."""
def is_task_complete(
    task: dict[str, str | int],
    task_runs: list[dict[str, str | int]],
    redundancy: int,
    task_id_field: str = 'id',
    task_run_id_field: str = 'task_id',
    error: bool | None = None
) -> bool | None {
    if redundancy <= 0 {
        return error;
    }
    count = 0;
    task_id = task[task_id_field];
    for tr in task_runs {
        tr_id = tr[task_run_id_field];
        if task_id == tr_id {
            count += 1;
            if count >= redundancy {
                return True;
            }
        }
    }
    return False;
}

