"""
appends the given argument to a command line such that CommandLineToArgvW will return
the argument string unchanged.
"""
def win_concat_quote(command_line: str, argument: str) -> str {
    result = (command_line + " ") if command_line else "";
    if argument {
        if len(argument.split()) == 1 {
            if '"' not in argument {
                result += argument;
                return result;
            }
        }
    }
    result += '"';
    it = 0;
    end = len(argument);
    while it < end {
        number_backslashes = 0;
        char = argument[it];
        while char == '\\' {
            it += 1;
            number_backslashes += 1;
            try {
                char = argument[it];
            } except IndexError {
                break;
            }
        }
        if it >= end {
            result += '\\' * (number_backslashes * 2);
            break;
        } elif char == '"' {
            result += '\\' * ((number_backslashes * 2) + 1);
            result += char;
        } else {
            result += '\\' * number_backslashes;
            result += char;
        }
        it += 1;
    }
    result += '"';
    return result;
}

"""
USAGE
-----
texstr = float2latex(f, ndigits=1)

Converts a float input into a latex-formatted
string with 'ndigits' (defaults to 1).

Adapted from:
http://stackoverflow.com/questions/13490292/format-number-using-latex-notation-in-python
"""
def float2latex(f: float, ndigits: int = 1) -> str {
    float_str = "{0:.%se}" % ndigits;
    float_str = float_str.format(f);
    (base, exponent) = float_str.split("e");
    return "${0} \times 10^{{{1}}}$".format(base, int(exponent));
}

"""Computes precision for a given positive prevalence from TPR and FPR."""
def precision_from_tpr_fpr(tpr: float, fpr: float, positive_prior: float) -> float {
    return (positive_prior * tpr) / ((positive_prior * tpr) + ((1 - positive_prior) * fpr));
}

"""Binary search on a sorted list with optional custom comparator."""
def binary_search(
    items: list[object],
    item: object,
    comparator: Callable[[object, object], int] = lambda (x: object, y: object) -> int {
        0 if x == y else 1 if x > y else -1
    },
    lo: int = 0,
    hi: int | None = None,
    insertion_index: bool = False
) -> int | tuple[int, int] {
    if hi is None {
        hi = len(items);
    }
    while lo < hi {
        mid = (lo + hi) // 2;
        comparison = comparator(item, items[mid]);
        if comparison == 0 {
            return mid if not insertion_index else (mid, mid);
        } elif comparison == 1 {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return -1 if not insertion_index else (-1, lo);
}

"""Returns whether x is (in turn order) between begin (inclusive) and end
(inclusive). This function assumes that x,
begin, end are smaller than the number of players (and at least 0).
If begin == end, this is only true if x == begin == end."""
def is_between_inclusive(x: int, begin: int, end: int) -> bool {
    return begin <= x <= end or end < begin <= x or x <= end < begin;
}

"""Get the number of rows and columns for the give number of plots.

    Returns how many rows and columns should be used to have the correct
    number of figures available. This doesn't return anything larger than
    3 columns, but the number of rows can be large.
    """
def subplot_dims(n_plots: int) -> tuple[int, int] {
    if n_plots > 9 {
        n_cols = 3;
        n_rows = (1 + n_plots) // n_cols;
    } elif n_plots < 2 {
        n_rows = n_cols = 1;
    } else {
        n_cols = 2;
        n_rows = (1 + n_plots) // n_cols;
    }
    return (n_rows, n_cols);
}

"""
    For some reason Prodigy was assigning the same hashes
    to every example in the data, which meant that when
    it looked at the saved annotations in the dataset to
    figure out which to exclude, it excluded all of them.

    Setting the _input_hash to the index of the candidate
    connection also makes lookup easier when we filter the
    candidates according to their annotation.
    """
def set_hashes(task: dict[str, int | str], i: int) -> dict[str, int | str] {
    task["_input_hash"] = i;
    task["_task_hash"] = -(i + 1);
    return task;
}

