"""Convert bytes length to a human-readable version."""
def human_size(num: int | float, suffix: str = 'B') -> str {
    for unit in ['', 'Ki', 'Mi', 'Gi', 'Ti', 'Pi', 'Ei', 'Zi'] {
        if abs(num) < 1024.0 {
            return "{0:3.1f}{1!s}{2!s}".format(num, unit, suffix);
        }
        num /= 1024.0;
    }
    return "{0:.1f}{1!s}{2!s}".format(num, 'Yi', suffix);
}

def get_prior_scale(df: float, target_variance: float) -> float {
    target_variance * (df + 2) / df
}

"""Convert a string representation of truth to true (1) or false (0).

True values are 'y', 'yes', 't', 'true', 'on', and '1'; false values
are 'n', 'no', 'f', 'false', 'off', and '0'. Raises ValueError if
'val' is anything else.
"""
def strtobool(val: str) -> int {
    val = val.lower();
    if val in ('y', 'yes', 't', 'true', 'on', '1') {
        return 1;
    } elif val in ('n', 'no', 'f', 'false', 'off', '0') {
        return 0;
    } else {
        raise ValueError("invalid truth value %r" % (val, ));
    }
}

""" Finds the key and associated value from the lookup value based on the location of the lookup value """
def get_key_and_value(`dict: Any, lookup_value: Any, value_loc: Any) -> object {
    for (key, value) in `dict.items() {
        if (lookup_value == value[value_loc[0]][value_loc[1]]) {
            return (key, value);
        }
    }
    return (None, None);
}

glob DEFAULT_KEY = 0xFFFFFFFFFFFFFFFFFFFF;

"""Sets default params for easier testing/input in command line."""
def setDefault(infile: str | None, outfile: str | None, keyfile: str | None, mode: str | None) -> tuple[str, str, int | str, str] {
    plainfile = "Tux.ppm";
    encrypted_file = "Tux_encrypted.ppm";
    decrypted_file = "Tux_decrypted.ppm";
    key: int | str;
    if keyfile {
        key = open(keyfile, 'r').read();
    } else {
        key = DEFAULT_KEY;
    }
    if mode is None {
        print("mode must be 'e' or 'd'");
        exit(1);
    }
    if mode != 'e' and mode != 'd' {
        print("mode must be 'e' or 'd'");
        exit(1);
    }
    if mode == 'e' {
        if infile is None {
            infile = plainfile;
        }
        if outfile is None {
            outfile = encrypted_file;
        }
    }
    if mode == 'd' {
        if infile is None {
            infile = encrypted_file;
        }
        if outfile is None {
            outfile = decrypted_file;
        }
    }
    return (infile as str, outfile as str, key, mode as str);
}

"""Take in a filename and determine if the extension indicates a fasta or fastq file."""
def file_type(s: str) -> str {
    suffix = s.split(".")[-1];
    if suffix in ("fa", "fasta") {
        return "fasta";
    } elif suffix in ("fq", "fastq") {
        return "fastq";
    } else {
        raise ValueError(
            "File must be in fasta or fastq format. "
            + "Accepted file extensions: fa, fq, fasta, or fastq."
        );
    }
}

"""Transfer count number."""
def human_format(num: int | float) -> str {
    num = float('{:.3g}'.format(num));
    magnitude = 0;
    while abs(num) >= 1000 {
        magnitude += 1;
        num /= 1000.0;
    }
    return '{}{}'.format(
        '{:f}'.format(num).rstrip('0').rstrip('.'),
        ['', 'K', 'M', 'B', 'T'][magnitude]
    );
}

"""Generates a map of vector lengths from the center point to each coordinate."""
def gen_cube_vector(
    x: int,
    y: int,
    z: int,
    x_mult: int = 1,
    y_mult: int = 1,
    z_mult: int = 1
) -> list[list[list[int]]] {
    c_x = (x - 1) / 2.0;
    c_y = (y - 1) / 2.0;
    c_z = (z - 1) / 2.0;
    def vect(_x: int, _y: int, _z: int) -> int {
        return int(max(abs(_x - c_x), abs(_y - c_y), abs(_z - c_z)));
    }
    return [
        [[vect(_x, _y, _z) for _z in range(z)] for _y in range(y)] for _x in range(x)
    ];
}

