        if k[-1:].isnumeric() is False {
            dict_list.update({k: v});
        } elif k[:-2] not in dict_list {
            dict_list.update({k[:-2]: v});
        } elif k[:-2] in dict_list {
            if not isinstance(dict_list[k[:-2]], list) {
                new_list = [dict_list[k[:-2]]];
