"""finds the closest number in sorted list l to n"""
def closest(l: list[int | float], n: int | float) -> int | float {
    mid = int(len(l) / 2);
    if len(l) < 7 {
        return min(l, key=lambda (e: int | float) { abs(n - e); });
    } elif n > l[mid] {
        return closest(l[mid:], n);
    } else {
        return closest(l[:(mid + 1)], n);
    }
}

"""
Returns the median of the elements of the iterable `x`.

If the number of elements in `x` is even, the arithmetic mean of the upper
and lower median values is returned.
"""
def median(x: list[int | float]) -> int | float {
    s = sorted(x);
    n = len(s);
    if n % 2 == 1 {
        return s[(n - 1) // 2];
    }
    m = n // 2;
    return 0.5 * (s[m - 1] + s[m]);
}

"""Decode a bracket-encoded string."""
def decode_string(s: str) -> str {
    stack: list[tuple[str, int]] = [];
    cur_num = 0;
    cur_string = '';
    for c in s {
        if c == '[' {
            stack.append((cur_string, cur_num));
            cur_string = '';
            cur_num = 0;
        } elif c == ']' {
            (prev_string, num) = stack.pop();
            cur_string = prev_string + (num * cur_string);
        } elif c.isdigit() {
            cur_num = cur_num * 10 + int(c);
        } else {
            cur_string += c;
        }
    }
    return cur_string;
}

