"""
Unlike the book, we don't require the max value be passed in and just find
it using "max". We also just create the output array B locally instead of
passing it in.
"""
def counting_sort(A: list[int], unused_0: int = 0, unused_1: int = 0) -> list[int] {
    k = max(A) + 1;
    B = [0 for i in range(len(A))];
    C = [0 for i in range(k)];
    for j in range(len(A)) {
        C[A[j]] = C[A[j]] + 1;
    }
    for i in range(1, k) {
        C[i] = C[i] + C[i - 1];
    }
    for j in reversed(range(len(A))) {
        B[C[A[j]] - 1] = A[j];
        C[A[j]] = C[A[j]] - 1;
    }
    return B;
}

"""Automatically chooses relevant unit for displaying a number of bytes."""
def _byte_str(num: int, unit: str = 'auto', precision: int = 2) -> str {
    abs_num = abs(num);
    if unit == 'auto' {
        if abs_num < 2.0 ** 10 {
            unit = 'KB';
        } elif abs_num < 2.0 ** 20 {
            unit = 'KB';
        } elif abs_num < 2.0 ** 30 {
            unit = 'MB';
        } elif abs_num < 2.0 ** 40 {
            unit = 'GB';
        } else {
            unit = 'TB';
        }
    }
    num_unit: float;
    if unit.lower().startswith('b') {
        num_unit = num;
    } elif unit.lower().startswith('k') {
        num_unit = num / (2.0 ** 10);
    } elif unit.lower().startswith('m') {
        num_unit = num / (2.0 ** 20);
    } elif unit.lower().startswith('g') {
        num_unit = num / (2.0 ** 30);
    } elif unit.lower().startswith('t') {
        num_unit = num / (2.0 ** 40);
    } else {
        raise ValueError('unknown num={!r} unit={!r}'.format(num, unit));
    }
    fmtstr = '{:.' + str(precision) + 'f}{}';
    return fmtstr.format(num_unit, unit);
}

