""" bottom up implementation of cut rod memoized algorithm """
def bottom_up_cut_rod(price: list[float], length: int) -> float {
    incomelst = [float('-Inf') for _ in range(length + 1)];
    incomelst[0] = 0;
    for j in range(1, length + 1) {
        income = float('-Inf');
        for i in range(j) {
            income = max(income, price[i] + incomelst[j - i - 1]);
        }
        incomelst[j] = income;
    }
    return incomelst[length];
}

"""
    http://code.activestate.com/recipes/198157-improve-dictionary-lookup-performance/
    Created by Raymond Hettinger on Sun, 4 May 2003 (PSF)
    Reduce average dictionary lookup time by making the internal tables more sparse.
    Improve dictionary sparsity.

    The dict.update() method makes space for non-overlapping keys.
    Giving it a dictionary with 100% overlap will build the same
    dictionary in the larger space.  The resulting dictionary will
    be no more that 1/3 full.  As a result, lookups require less
    than 1.5 probes on average.

    Example:
    >>> sparsify({1: 3, 4: 5})
    {1: 3, 4: 5}
    """
def sparsify(d: dict[int, int]) -> dict[int, int] {
    e = d.copy();
    d.update(e);
    return d;
}

"""
    Generate full taxonomic lineage from a taxid
    Args:
        taxid (str): taxid
        names_map (dict[str:str]): the taxonomic names for each taxid node
        ranks_map (dict[str:str]): the parent node for each taxid
    Returns:
        taxonomy (str): full taxonomic lineage string

    """
def get_full_name(taxid: str, names_map: dict[str, str], ranks_map: dict[str, str]) -> str {
    taxid_lineage = list();
    while True {
        taxid_lineage.append(taxid);
        if taxid not in ranks_map {
            break;
        }
        new_taxid = ranks_map[taxid];
        if taxid == new_taxid {
            break;
        } else {
            taxid = new_taxid;
        }
    }
    names_lineage = [names_map[t] for t in taxid_lineage];
    return ";".join(reversed(names_lineage));
}

"""Clips the thresholds for binary search based on current word counts.

    The upper threshold parameter typically has a large default value that can
    result in many iterations of unnecessary search. Thus we clip the upper and
    lower bounds of search to the maximum and the minimum wordcount values.

    Args:
      word_counts: list of (string, int) tuples
      upper_thresh: int, upper threshold for binary search
      lower_thresh: int, lower threshold for binary search

    Returns:
      upper_search: int, clipped upper threshold for binary search
      lower_search: int, clipped lower threshold for binary search
    """
def get_search_threshs(
    word_counts: list[tuple[str, int]], upper_thresh: int | None, lower_thresh: int | None
) -> tuple[int, int] {
    counts = [count for (_, count) in word_counts];
    max_count = max(counts);
    min_count = min(counts);
    if upper_thresh is None {
        upper_search = max_count;
    } else {
        upper_search = max_count if max_count < upper_thresh else upper_thresh;
    }
    if lower_thresh is None {
        lower_search = min_count;
    } else {
        lower_search = min_count if min_count > lower_thresh else lower_thresh;
    }
    return (upper_search, lower_search);
}

