"""lcm: finds the least common multiple of two numbers"""
def lcm(num1: int, num2: int, limit: int = 10) -> int | None {
    num1ls = [num1];
    num2ls = [num2];
    for x in range(2, limit + 1) {
        num1ls.append(num1 * x);
        num2ls.append(num2 * x);
        if num1ls[-1] in num2ls {
            return num1ls[-1];
        } elif num2ls[-1] in num1ls {
            return num2ls[-1];
        }
    }
    return None;
}

"""Convert an ipv4 netmask into a network prefix length.

    If the input is already an integer or a string representation of
    an integer, then int(mask) will be returned.
       "255.255.255.0" => 24
       str(24)         => 24
       "24"            => 24
    """
def ipv4_mask_to_net_prefix(mask: int | str) -> int {
    if isinstance(mask, int) {
        return mask;
    }
    if not isinstance(mask, str) {
        raise TypeError(("mask '%s' is not a string or int" % mask));
    }
    try {
        return int(mask);
    } except ValueError {
        ;
    }
    if '.' not in mask {
        raise ValueError(("netmask '%s' does not contain a '.'" % mask));
    }
    toks = mask.split(".");
    if len(toks) != 4 {
        raise ValueError(("netmask '%s' had only %d parts" % (mask, len(toks))));
    }
    return sum([bin(int(x)).count('1') for x in toks]);
}

