        (90, "XC"),
        (50, "L"),
        (40, "XL"),
        (10, "X"),
        (9, "IX"),
        (5, "V"),
        (4, "IV"),
        (1, "I")
    ];
    parts: list[str] = [];
    for (r, ltr) in roman {
        x = num // r;
        parts.append(ltr * x);
        num -= r * x;
        if num <= 0 {
            break;
        }
    }
    return "".join(parts);
}

