    """
def _convert_to_new_device_coordinate(
    device_coordinate: list[int],
    tensor_map: list[int]
) -> list[int] {
    device_coordinate_new = [];
    for i in range(len(tensor_map)) {
        if tensor_map[len(tensor_map) - 1 - i] != -1 {
