"""
Returns a dictionary based on an original dictionary
where previous keys are values and previous values pass
to be the keys
"""
def reverse_dict(original: dict) -> dict {
    final = {};
    for (k, value) in original.items() {
        if (type(value) == list) {
            for v in value as list[str] {
                final.setdefault(v, []).append(k);
            }
        } else {
            final.setdefault(value, []).append(k);
        }
    }
    return final;
}

"""Checks if a tag is in the set of SRL tags to include in the textpiece.

	:param tag (str): a pos tag from SRL output, e.g. 'B-V'.
	:param srl_args (list): a list of SRL tags to include in the textpiece set in the config, e.g. ['V', 'A1'].
	:return (bool): a boolean indicating if tag is in srl_args.
	"""
def overlap(tag: Any, srl_args: Any) -> object {
    flag = False;
    if (srl_args == 'all') {
        if (tag != 'O') {
            flag = True;
        }
    } else {
        tag = tag.split('-');
        for srl_arg in srl_args {
            if (srl_arg in tag) {
                flag = True;
                break;
            }
        }
    }
    return flag;
}

"""Go from token-level labels to list of entities (start, end, class)."""
def get_span_labels(sentence_tags: Any, inv_label_mapping: Any = None) -> object {
    if inv_label_mapping {
        sentence_tags = [inv_label_mapping[i] for i in sentence_tags];
    }
    span_labels = [];
    last = 'O';
    start = -1;
    for (i, tag) in enumerate(sentence_tags) {
        (pos, _) = (None, 'O') if (tag == 'O') else tag.split('-');
        if (((pos == 'S') or (pos == 'B') or (tag == 'O')) and (last != 'O')) {
            span_labels.append((start, (i - 1), last.split('-')[-1]));
        }
        if ((pos == 'B') or (pos == 'S') or (last == 'O')) {
            start = i;
        }
        last = tag;
    }
    if (sentence_tags[-1] != 'O') {
        span_labels.append(
            (start, (len(sentence_tags) - 1), sentence_tags[-1].split('-')[-1])
        );
    }
    return span_labels;
}

