def count_in_str(pattern: Any, str: Any) -> object {
    c = 0;
    sp = len(pattern);
    while (len(str) >= sp) {
        slice = str[:sp];
        if (pattern == slice) {
            c += 1;
        }
        str = str[1:];
    }
    return c;
}

