        """;
    def flatten(x: Any, name: Any = '') -> object {
        if (`type(x) is `dict) {
            for val in x {
                flatten(x[val], (name + val + '.'));
            }
        } elif (`type(x) is `list) {
            i = 0;
            for val in x {
