"""Parse an attribute line.

    Arguments:
    line -- a single line from the tlpdb

    Returns:
    A dictionary of attributes

    Example input lines:

        arch=x86_64-darwin size=1
        details="Package introduction" language="de"
        RELOC/doc/platex/pxbase/README details="Readme" language="ja"

    """
def _attributes_from_line(line: Any) -> object {
    key = None;
    value = None;
    chars = [];
    quote_count = 0;
    attrs = {};
    for c in line {
        if (c == "=") {
            if (key == None) {
                assert (quote_count == 0) , ("possibly quoted key in line %s" % line);
                key = "".join(chars);
                chars = [];
            } else {
                chars.append(c);
            }
        } elif (c == "\"") {
            quote_count += 1;
        } elif (c == " ") {
            if ((quote_count % 2) == 0) {
                assert (key != None) , ("no key found for %s" % line);
                assert (key not in attrs) , ("key already assigned for line %s" % line);
                attrs[key] = "".join(chars);
                chars = [];
                key = None;
                quote_count = 0;
            } else {
                chars.append(c);
            }
        } else {
            chars.append(c);
        }
    }
    assert (key != None) , ("no key found for %s" % line);
    assert len(chars) , ("no values found for line %s" % line);
    attrs[key] = "".join(chars);
    return attrs;
}

"""Function that converts a board (in FEN notation) in a list of lists of lines of the chess board"""
def boardToArray(board: str) -> list[list[str]] {
    board = board.replace("1", "-").replace("2", "--").replace("3", "---").replace("4", "----").replace("5", "-----").replace("6", "------").replace("7", "-------").replace("8", "--------");
    current_line = [];
    list_board = [];
    for (i, char) in enumerate(board) {
        if char == ' ' {
            list_board.append(current_line);
            break;
        }
        if (i + 1) % 9 == 0 {
            list_board.append(current_line);
            current_line = [];
        } else {
            current_line.append(char);
        }
    }
    return list_board;
}

