"""
def flatten_dict(dct: dict[str, object], key_string: str = "") -> list[tuple[str, object]] {
    result = [];
    for key in dct {
        updated_key_string = key_string + key + ".";
        if isinstance(dct[key], dict) {
            result = result + flatten_dict(dct[key], updated_key_string);
