"""Generate paths to examine from a variable-type template."""
def _expand_check_paths(
    template: str | list[str | list | dict] | dict[str, str | list | dict],
    lookup_key: str | None
) -> list[str] {
    check_paths = [];
    if isinstance(template, dict) {
        if lookup_key is None {
            check_paths += _expand_check_paths(list(template.values()), lookup_key);
        } else {
            check_paths += _expand_check_paths(template.get(lookup_key, []), lookup_key);
        }
    } elif isinstance(template, list) {
        for value in template {
            check_paths += _expand_check_paths(value, lookup_key);
        }
    } else {
        check_paths += [template];
    }
    return check_paths;
}

"""Transforms series of water usage in 15 minutes intervals into 1 hour intervals.

    :param usage_list: list of numbers
    :return: list of numbers(usage hourly)
    """
def usage15minTo1hTransform(usage_list: Any) -> object {
    usage = [];
    for i in range(0, (len(usage_list) - 1), 4) {
        h = (
            float(usage_list[i])
            + float(usage_list[(i + 1)])
            + float(usage_list[(i + 2)])
            + float(usage_list[(i + 3)])
        );
        usage.append(round(h, 2));
    }
    return usage;
}

