) -> tuple[str | bool, int] {
    if type(in_heart_rate) is not dict {
        return ("The input was not a dictionary", 400);
    }
    for key in heart_rate_expected_keys {
        if key not in in_heart_rate {
            return ("The key {} is missing from input".format(key), 400);
