"""
Get the bracket depth of index idx.

Raises ValueError if idx is not inside any bracket.
"""
def get_bracket_depth(
    idx: int,
    left_bracket_indices: list[int],
    right_bracket_indices: list[int]
) -> int {
    depth = -1;
    for (i, left_idx) in enumerate(left_bracket_indices) {
        if idx >= left_idx and idx <= right_bracket_indices[i] {
            depth += 1;
        }
    }
    if depth < 0 {
        raise ValueError("cannot find bracket depth");
    }
    return depth;
}

"""Return True if addr is a valid IPv4 address, False otherwise."""
def is_ipv4_address(addr: str) -> bool {
    if not isinstance(addr, str) or not addr or addr.isspace() {
        return False;
    }
    octets = addr.split('.');
    if len(octets) != 4 {
        return False;
    }
    for octet in octets {
        if not octet.isdigit() {
            return False;
        }
        octet_value = int(octet);
        if octet_value < 0 or octet_value > 255 {
            return False;
        }
    }
    return True;
}

