"""Transpose a ttx classDef

    {glyph_name: idx, glyph_name: idx} --> {idx: [glyph_name, glyph_name]}

    Classdef 0 is not defined in the font. It is created by subtracting
    the glyphs found in the lookup coverage against all the glyphs used to
    define the other classes."""
def _kern_class(class_definition: Any, coverage_glyphs: Any) -> object {
    classes = {};
    seen_glyphs = `set();
    for (glyph, idx) in class_definition.items() {
        if (idx not in classes) {
            classes[idx] = [];
        }
        classes[idx].append(glyph);
        seen_glyphs.add(glyph);
    }
    classes[0] = `set(coverage_glyphs) - seen_glyphs;
    return classes;
}

"""A dynamic programming version of Fibonacci, linear space"""
def dp_fib_ls(n: int) -> object {
    res = [0, 1];
    for i in range(2, (n + 1)) {
        res.append((res[(i - 2)] + res[(i - 1)]));
    }
    return res[n];
}

"""
	Given a string, return a new string that has
	transformed based on the input:
		1. Change case of every character, ie. lower
		case to upper case, upper case to lower case.
		2. Reverse the order of words from the input.

	Note: You will have to handle multiple spaces, and
	leading/trailing spaces.

	You may assume the input only contain English
	alphabet and spaces.
	:param s:
	:return:
	"""
def string_transformer(s: str) -> str {
    s_arr = s.split(' ')[::-1];
    for (i, word) in enumerate(s_arr) {
        s_arr[i] = ''.join(
            char.upper() if char.islower() else char.lower() for char in word
        );
    }
    return ' '.join(s_arr);
}

