}

"""
    Tries to determine if a buffer is empty.

    @type buffer: str
    @param buffer: Buffer to test if it is empty.

    @rtype: bool
    @return: C{True} if the given buffer is empty, i.e. full of zeros,
        C{False} if it doesn't.
    """
def allZero(buffer: Any) -> object {
    allZero = True;
    for byte in buffer {
        if (byte != 0) {
            allZero = False;
            break;
        }
    }
    return allZero;
}

"""http://en.wikipedia.org/wiki/Luhn_algorithm ."""
def luhn_checksum(check_number: int | str) -> int {
    def digits_of(n: int | str) -> list[int] {
        return [int(d) for d in str(n)];
    }
    digits = digits_of(check_number);
    odd_digits = digits[-1::-2];
    even_digits = digits[-2::-2];
    checksum = 0;
    checksum += sum(odd_digits);
    for d in even_digits {
        checksum += sum(digits_of(d * 2));
    }
    return checksum % 10;
}

